package com.mfg.eam.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;
@Entity @Table(name="eam_fault",catalog="src_eam") @Getter @Setter @NoArgsConstructor public class EquipmentFault{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="fault_no")private String faultNo;@Column(name="equipment_code")private String equipmentCode;@Column(name="equipment_name")private String equipmentName;@Column(name="fault_type")private String faultType;@Column(name="fault_level")private String faultLevel;@Column(name="fault_desc")private String faultDesc;@Column(name="fault_time")private LocalDateTime faultTime;@Column(name="work_order_no")private String workOrderNo;@Column(name="prod_order_no")private String prodOrderNo;@Column(name="operation_code")private String operationCode;@Column(name="fault_status")private String status="OPEN";@Column(name="reported_by")private String reportedBy;}
